INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28h-2016-q21','exam-sg','Web攻撃・XSS','standard','single_choice','【2016年度 平成28年春期 午前 問21】クロスサイトスクリプティング（XSS）に該当するものはどれか。','[{"id":"a","text":"入力文字列を悪用してデータベースの不正な取得・改ざん・削除を可能にする。"},{"id":"b","text":"大量のパケットを送り付け，サービスを提供不能にする。"},{"id":"c","text":"メモリ領域を超える読み書きでプログラムを異常終了させたり，不正コードを実行させたりする。"},{"id":"d","text":"罠のWebページを閲覧させ，脆弱なWebサーバの応答に埋め込まれた不正スクリプトをブラウザで実行させる。"}]','"d"','正解はエ。XSSはWebページに混入したスクリプトを利用者のブラウザで実行させ，情報を盗むなどの攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q22','exam-sg','Web攻撃・クリックジャッキング','standard','single_choice','【2016年度 平成28年春期 午前 問22】クリックジャッキング攻撃に該当するものはどれか。','[{"id":"a","text":"応答を分割させてブラウザのキャッシュを偽造する。"},{"id":"b","text":"WebサイトA上に透明化した標的サイトBを重ね，A上の操作に見せかけてB上で操作させる。"},{"id":"c","text":"非活性タブの内容を偽ログインページに置き換え，利用者に操作させる。"},{"id":"d","text":"ブラウザ設定を変更して閲覧履歴やパスワードを盗み出す。"}]','"b"','正解はイ。クリックジャッキングは透明な画面などを重ね，利用者が意図しないボタン操作を行うよう誘導する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q23','exam-sg','電子署名・完全性','standard','single_choice','【2016年度 平成28年春期 午前 問23】送信者Aが文書ファイルとディジタル署名を受信者Bに送信した。Bが署名検証鍵を保有し，署名生成鍵を知らないとき，できることはどれか。','[{"id":"a","text":"署名・文書・検証鍵を比較して，改ざんされた部分を特定できる。"},{"id":"b","text":"認証局に問い合わせて，文書がウイルスに感染していないことを確認できる。"},{"id":"c","text":"文書が改ざんされていないことと，署名が対応する署名生成鍵で作られたことを確認できる。"},{"id":"d","text":"文書と署名のどちらが改ざんされたかを必ず区別できる。"}]','"c"','正解はウ。電子署名の検証により，署名対象データの完全性と，対応する秘密鍵で署名されたことを確認できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q24','exam-sg','公開鍵基盤・認証局','standard','single_choice','【2016年度 平成28年春期 午前 問24】公開鍵暗号を利用した電子商取引において，認証局（CA）の役割はどれか。','[{"id":"a","text":"取引当事者間で共有する秘密鍵を管理する。"},{"id":"b","text":"取引当事者の公開鍵に対するディジタル証明書を発行する。"},{"id":"c","text":"取引当事者のディジタル署名を管理する。"},{"id":"d","text":"取引当事者のパスワードを管理する。"}]','"b"','正解はイ。認証局は公開鍵と主体の対応を証明するディジタル証明書を発行・管理する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q25','exam-sg','マルウェア・ドライブバイダウンロード','standard','single_choice','【2016年度 平成28年春期 午前 問25】ドライブバイダウンロード攻撃の説明はどれか。','[{"id":"a","text":"USBメモリ接続時に自動実行機能を使ってウイルスを実行する。"},{"id":"b","text":"ファイルを暗号化し，復号と引換えに金銭を要求する。"},{"id":"c","text":"Webサイトを閲覧したとき，利用者が気付かないうちに不正プログラムがPCへ転送される。"},{"id":"d","text":"無線LANの電波を傍受して，設定が脆弱なアクセスポイントを探す。"}]','"c"','正解はウ。ドライブバイダウンロードは，Web閲覧などをきっかけに利用者の意図に反して不正プログラムを送り込む攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q26','exam-sg','パスワード攻撃・パスワードリスト','standard','single_choice','【2016年度 平成28年春期 午前 問26】パスワードリスト攻撃の手口に該当するものはどれか。','[{"id":"a","text":"辞書にある単語をパスワードにしている利用者を狙い，辞書の単語でログインを試す。"},{"id":"b","text":"数字4桁のパスワードを総当たりで試す。"},{"id":"c","text":"短いパスワードの組合せを総当たりで試す。"},{"id":"d","text":"他サイトから不正取得した利用者IDとパスワードの一覧を使い，別サイトへのログインを試す。"}]','"d"','正解はエ。パスワードリスト攻撃は，漏えいしたID・パスワードの組を他のサービスで試す攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q27','exam-sg','マルウェア・バックドア','standard','single_choice','【2016年度 平成28年春期 午前 問27】バックドアに該当するものはどれか。','[{"id":"a","text":"攻撃を受けてロックアウトされた利用者アカウント"},{"id":"b","text":"システム内に攻撃者が秘密裏に作成した利用者アカウント"},{"id":"c","text":"退職などを理由に管理者が無効にした利用者アカウント"},{"id":"d","text":"パスワードの有効期限が切れた利用者アカウント"}]','"b"','正解はイ。バックドアは正規の認証やアクセス制御を回避して侵入できるよう，秘密裏に設けられた経路や仕組みである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q28','exam-sg','暗号技術・IPsec','standard','single_choice','【2016年度 平成28年春期 午前 問28】PCとサーバ間でIPsecによる暗号化通信を行い，AESを使う場合に用いるべき鍵はどれか。','[{"id":"a","text":"PCだけが所有する秘密鍵"},{"id":"b","text":"PCとサーバで共有された共通鍵"},{"id":"c","text":"PCの公開鍵"},{"id":"d","text":"サーバの公開鍵"}]','"b"','正解はイ。IPsecでAESなどの共通鍵暗号を使う場合，通信相手間で共有した共通鍵を利用する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q29','exam-sg','ネットワーク診断・ポートスキャン','standard','single_choice','【2016年度 平成28年春期 午前 問29】攻撃者がシステムに侵入するとき，ポートスキャンを行う目的はどれか。','[{"id":"a","text":"事前調査の段階で，攻撃できそうなサービスがあるかを調査する。"},{"id":"b","text":"権限取得の段階で，奪取できそうなアカウントを調査する。"},{"id":"c","text":"不正実行の段階で，有益な利用者情報があるかを調査する。"},{"id":"d","text":"後処理の段階で，ログに攻撃の痕跡が残っていないかを調査する。"}]','"a"','正解はア。ポートスキャンは稼働中のサービスや開放ポートを調べる事前調査に使われる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q30','exam-sg','公開鍵暗号・メール暗号化','standard','single_choice','【2016年度 平成28年春期 午前 問30】AがBの公開鍵で暗号化したメールをBとCに送信した。公開鍵は3人とも知っており，秘密鍵は本人だけが持つ場合，適切なものはどれか。','[{"id":"a","text":"BとCの両方がBの公開鍵で復号できる。"},{"id":"b","text":"BとCの両方がそれぞれの秘密鍵で復号できる。"},{"id":"c","text":"BだけがAの公開鍵で復号できる。"},{"id":"d","text":"Bだけが自身の秘密鍵で復号できる。"}]','"d"','正解はエ。Bの公開鍵で暗号化されたデータは，対応するBの秘密鍵でのみ復号できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja');
